'use client';
import { useRef, type CSSProperties, type KeyboardEvent } from 'react';
import { cx } from '../lib/cx';
import { useControllable } from '../lib/hooks';
import { Icon, type IconName } from '../lib/icons';
import { enter, Fold, Swap, Tip } from '../lib/motion';
import '../designme.css';
import './trace-view.css';

export type SpanKind = 'agent' | 'llm' | 'tool' | 'retrieval';

export interface TraceSpan {
  id: string;
  /** Like "Plan the steps" or the tool's name, "fetch_page" */
  name: string;
  kind: SpanKind;
  /** When it started, in seconds from the start of the run */
  start: number;
  /** How long it took, in seconds. Leave it out while it runs: its bar grows to `time` */
  duration?: number;
  /** Tokens it used. An agent span without its own count adds up every span under it */
  tokens?: number;
  /** What went in and what came out, shown when the span is opened */
  input?: string;
  output?: string;
  children?: TraceSpan[];
}

export interface TraceViewProps {
  /** The run's name, like "Pricing research" */
  title: string;
  /** The run's top spans, usually one root with everything nested under it */
  spans: TraceSpan[];
  /** Seconds into the run while it streams in: spans that start later stay hidden, and running ones reach this far.
      Leave it out once the run is over */
  time?: number;
  /** Seconds the time axis covers. Defaults to the run's length, rounded up to a whole second */
  axis?: number;
  /** A tool call that takes longer than this many seconds turns amber and is tagged slow. Defaults to 2 */
  slowAfter?: number;
  /** The line under the title. Defaults to "Running · 4 spans", then "Done · 7 spans, 1 slow" */
  status?: string;
  /** The id of the open span, whose details show under the waterfall. null closes them */
  selected?: string | null;
  defaultSelected?: string | null;
  onSelectedChange?: (id: string | null) => void;
  className?: string;
}

const KIND: Record<SpanKind, [string, IconName, string]> = {
  agent: ['Agent', 'cpu', 'var(--dm-muted)'], llm: ['LLM call', 'spark', 'var(--dm-c2)'], tool: ['Tool call', 'term', 'var(--dm-c6)'], retrieval: ['Retrieval', 'search', 'var(--dm-c3)']
};
const sec = (v: number) => v.toFixed(2) + 's';
const short = (v: number) => v >= 1000 ? (v / 1000).toFixed(1) + 'k' : String(Math.round(v));
const tokensOf = (s: TraceSpan): number => s.tokens ?? (s.children ?? []).reduce((a, k) => a + tokensOf(k), 0);

type Row = { s: TraceSpan; lv: number; up?: Row };

/** One agent run as an observability waterfall: every span (LLM call, tool call, retrieval, sub-agent) on a shared time
    axis, nested under the span that started it with a tree's guides, with its tokens and latency. Each kind has its colour
    and a count in the key; while the run streams a playhead marks now and running bars glow at their leading edge. A slow
    tool call turns amber and hatched, and any span opens to show where it sat in the run, its input, output, latency and tokens. */
export function TraceView({ title, spans, time, axis, slowAfter = 2, status, selected, defaultSelected = null, onSelectedChange, className }: TraceViewProps) {
  const [open, setOpen] = useControllable(selected, defaultSelected, onSelectedChange);
  const rows = useRef<HTMLDivElement>(null);
  const all: Row[] = [];
  (function walk(list: TraceSpan[], lv: number, up?: Row) { list.forEach(s => { const row = { s, lv, up }; all.push(row); if (s.children) walk(s.children, lv + 1, row); }); })(spans, 0);
  const end = Math.max(0, ...all.map(({ s }) => s.start + (s.duration ?? Math.max(0, (time ?? s.start) - s.start))));
  const span = axis ?? Math.max(1, Math.ceil(end));
  const now = time ?? Infinity;
  const shown = all.filter(({ s }) => s.start <= now);
  // the tree's guides: a line on down past a parent's mark, an elbow into each child, and the lines of ancestors whose own
  // siblings are still to come
  const later = (x: Row) => shown.some(y => y !== x && y.up === x.up && all.indexOf(y) > all.indexOf(x));
  const guides = (x: Row) => {
    const g: { x: number; cls?: string }[] = [];
    for (let a = x.up; a && a.up; a = a.up) if (later(a)) g.push({ x: a.lv - 1 });
    if (x.up) g.push({ x: x.lv - 1, cls: cx('dm-el', !later(x) && 'dm-end') });
    if (shown.some(y => y.up === x)) g.push({ x: x.lv, cls: 'dm-dn' });
    return g;
  };
  const KEYS: SpanKind[] = ['llm', 'tool', 'retrieval'];
  const took = (s: TraceSpan) => s.duration !== undefined ? Math.min(s.duration, now - s.start) : Math.max(0, (time ?? s.start) - s.start);
  const running = (s: TraceSpan) => s.duration === undefined || now < s.start + s.duration;
  const slow = (s: TraceSpan) => s.kind === 'tool' && took(s) > slowAfter;
  const nSlow = shown.filter(({ s }) => slow(s)).length;
  const live = shown.some(({ s }) => running(s));
  const line = status ?? (live ? `Running · ${shown.length} span${shown.length === 1 ? '' : 's'}` : `Done · ${shown.length} spans${nSlow ? `, ${nSlow} slow` : ''}`);
  // a label every other tick, and a faint line on every tick
  const tick = span <= 6 ? 1 : span <= 15 ? 2 : span <= 30 ? 5 : 10;
  const labels = Array.from({ length: Math.floor(span / tick / 2) + 1 }, (_, i) => i * tick * 2).filter(v => v < span);
  const grid: CSSProperties = { backgroundSize: `${(tick / span) * 100}% 100%` };
  const sel = open ? all.find(({ s }) => s.id === open)?.s : undefined;
  // the details keep the last span while they fold shut
  const last = useRef<TraceSpan | undefined>(undefined); if (sel) last.current = sel;
  const cur = sel ?? last.current;

  const onKey = (e: KeyboardEvent<HTMLDivElement>) => {
    const btns = [...(rows.current?.querySelectorAll<HTMLElement>('.dm-trv-r') ?? [])], i = btns.indexOf(document.activeElement as HTMLElement);
    if (i < 0) return;
    const go = e.key === 'ArrowDown' ? btns[i + 1] : e.key === 'ArrowUp' ? btns[i - 1] : e.key === 'Home' ? btns[0] : e.key === 'End' ? btns[btns.length - 1] : null;
    if (!go && !['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(e.key)) return;
    e.preventDefault(); go?.focus({ preventScroll: true });
  };
  // closing hands focus back to the span, if it was inside the details
  const close = (back: boolean) => {
    const id = open; setOpen(null);
    if (back && id) rows.current?.querySelector<HTMLElement>(`[data-id="${CSS.escape(id)}"]`)?.focus({ preventScroll: true });
  };

  return (
    <div data-dm="" className={cx('dm-trv dm-panel', live && time !== undefined && time > 0 && 'dm-live', className)} style={{ '--dm-now': Math.min(end, now) / span } as CSSProperties}
      onKeyDown={e => { if (e.key === 'Escape' && open) close(true); }}>
      <div className="dm-trv-h">
        <div className="dm-trv-ht"><b>{title}</b><span className="dm-muted dm-trv-st" aria-live="polite"><Swap>{line}</Swap></span></div>
        <span className="dm-trv-tot dm-num">{sec(Math.min(end, now))}</span>
      </div>
      <div className="dm-trv-lg" role="list" aria-label="Spans by kind">
        {KEYS.map(k => { const n = shown.filter(({ s }) => s.kind === k).length;
          return <span key={k} role="listitem" className={cx(!n && 'dm-z')} style={{ '--dm-k': KIND[k][2] } as CSSProperties}><i />{KIND[k][0]} <b key={n} className={cx('dm-num', n > 0 && 'dm-enter')}>{n}</b></span>; })}
      </div>
      <div className="dm-trv-ax" aria-hidden="true">
        <span>Span</span>
        <span className="dm-trv-sc">{labels.map(v => <span key={v} style={{ left: `${(v / span) * 100}%` }}>{v}s</span>)}</span>
        <span className="dm-trv-tk">Tokens</span><span className="dm-trv-ms">Time</span>
      </div>
      <div ref={rows} className={cx('dm-trv-rows', sel && 'dm-sel')} role="group" aria-label="Spans" onKeyDown={onKey}>
        {shown.map(row => {
          const { s, lv } = row;
          const [kind, icon, col] = KIND[s.kind], w = took(s), tk = tokensOf(s), run = running(s), sl = slow(s);
          const why = `Over the ${slowAfter}s budget for a tool call`;
          return (
            <button key={s.id} type="button" data-id={s.id} data-k={s.kind} className={cx('dm-trv-r dm-enter', !lv && 'dm-root', run && 'dm-run', sl && 'dm-slow')}
              style={{ '--dm-k': col, '--dm-lv': lv } as CSSProperties} aria-expanded={open === s.id}
              aria-label={`${s.name}, ${kind}, ${run ? 'running, ' : ''}${sec(w)}, ${Math.round(tk).toLocaleString('en-US')} tokens${sl ? ', slow' : ''}`}
              onClick={() => setOpen(open === s.id ? null : s.id)}>
              <span className="dm-trv-n">
                <span className="dm-trv-g" aria-hidden="true">{guides(row).map((g, i) => <i key={i} className={g.cls} style={{ '--dm-x': g.x } as CSSProperties} />)}</span>
                <Tip label={kind}><span className="dm-trv-k"><Icon name={icon} size="xs" /></span></Tip>
                <span className="dm-trv-nm">{s.name}</span>
                {sl && <Tip label={why}><span className={cx('dm-tag dm-warn', enter().className)}>slow</span></Tip>}
              </span>
              <span className="dm-trv-b" style={grid}><i style={{ left: `${(s.start / span) * 100}%`, width: `${(w / span) * 100}%` }} /></span>
              <span className="dm-trv-tk dm-num">{short(tk)}</span>
              {sl ? <Tip label={why}><span className="dm-trv-ms dm-num">{sec(w)}</span></Tip> : <span className="dm-trv-ms dm-num">{sec(w)}</span>}
            </button>
          );
        })}
      </div>
      <Fold open={!!sel} className="dm-trv-dt">
        {cur && (
          <div key={cur.id} className="dm-trv-dc dm-enter" role="region" aria-label="Span details">
            <div className="dm-trv-dh">
              <span className="dm-trv-k" style={{ '--dm-k': KIND[cur.kind][2] } as CSSProperties}><Icon name={KIND[cur.kind][1]} size="xs" /></span>
              <b>{cur.name}</b>{slow(cur) && <span className="dm-tag dm-warn">slow</span>}
              <Tip label="Close"><button type="button" className="dm-ib dm-trv-x" aria-label="Close details" onClick={e => close(e.currentTarget.contains(document.activeElement))}><Icon name="x" /></button></Tip>
            </div>
            <div className="dm-trv-pos" aria-hidden="true" style={{ '--dm-k': KIND[cur.kind][2] } as CSSProperties}>
              <i style={{ left: `${(cur.start / span) * 100}%`, width: `${(took(cur) / span) * 100}%` }} />
            </div>
            <div className="dm-trv-kv">
              <div><span>Kind</span><b>{KIND[cur.kind][0]}</b></div>
              <div><span>Starts at</span><b className="dm-num">{sec(cur.start)}</b></div>
              <div><span>Latency</span><b className="dm-num">{sec(took(cur))}</b></div>
              <div><span>Tokens</span><b className="dm-num">{Math.round(tokensOf(cur)).toLocaleString('en-US')}</b></div>
            </div>
            <div className="dm-trv-io">
              <span>Input</span><code>{cur.input ?? '–'}</code>
              <span>Output</span><code>{running(cur) ? 'Running…' : cur.output ?? '–'}</code>
            </div>
          </div>
        )}
      </Fold>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Trace view ---------- */
/* one agent run as a waterfall: every span on a shared time axis, nested under the span that started it, with its tokens
   and latency. Each kind has its colour (the chart palette's identity slots): its mark, its bar and its count in the key.
   While the run streams, a playhead marks now and the running bars glow at their leading edge. A span over its time budget
   turns amber and hatched, and any span opens to show where it sat in the run, its input and its output */
.dm-trv{width:100%;max-width:720px;margin:0 auto;padding:6px;container-type:inline-size;--dm-cols:minmax(0,11fr) minmax(0,8fr) 40px 44px}
.dm-trv-h{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-3);padding:var(--dm-s-2) 10px 6px}
.dm-trv-ht{display:flex;flex-direction:column;min-width:0}
.dm-trv-ht b{font-weight:500;font-size:14px}
.dm-trv-st{font-size:12.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-trv-tot{font-size:14px;font-weight:500;flex:none}
/* the key: each kind with its colour and how many of its spans have started */
.dm-trv-lg{display:flex;flex-wrap:wrap;gap:2px var(--dm-s-3);padding:0 10px var(--dm-s-2);font-size:12px;color:var(--dm-muted)}
.dm-trv-lg span{display:inline-flex;align-items:center;gap:5px;white-space:nowrap;transition:color .3s}
.dm-trv-lg i{width:8px;height:8px;border-radius:2px;background:var(--dm-k);flex:none}
.dm-trv-lg b{font-weight:500;color:var(--dm-fg2)}
.dm-trv-lg span.dm-z{color:var(--dm-dis)}.dm-trv-lg span.dm-z b{color:inherit}.dm-trv-lg span.dm-z i{opacity:.45}
.dm-trv-ax,.dm-trv-r{display:grid;grid-template-columns:var(--dm-cols);align-items:center;gap:var(--dm-s-2);padding:0 10px}
.dm-trv-ax{height:30px;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:12px;color:var(--dm-muted)}
.dm-trv-tk,.dm-trv-ms{text-align:right;white-space:nowrap}
.dm-trv-sc{position:relative;height:18px}
.dm-trv-sc span{position:absolute;top:0;transform:translateX(-50%);font-size:12px}
.dm-trv-sc span:first-child{transform:none}
.dm-trv-rows{display:flex;flex-direction:column;padding-bottom:var(--dm-s-1)}
.dm-trv-r{width:100%;min-height:32px;border-radius:10px;font-size:13px;text-align:left;transition:background .16s}
@media (hover:hover) and (pointer:fine){.dm-trv-r:hover{background:var(--dm-row)}}
.dm-trv-r[aria-expanded="true"]{background:var(--dm-sel)}
.dm-trv-r[aria-expanded="true"] .dm-trv-tk{color:var(--dm-fg2)}
.dm-trv-r:focus-visible{outline:0;box-shadow:inset 0 0 0 2px var(--dm-focus)}
.dm-trv-n{position:relative;display:flex;align-items:center;gap:6px;min-width:0;align-self:stretch;padding-left:calc(var(--dm-lv,0) * 16px)}
.dm-trv-k{position:relative;z-index:1;width:18px;height:18px;display:grid;place-items:center;flex:none;border-radius:5px;color:color-mix(in srgb,var(--dm-k) 70%,var(--dm-fg));background:color-mix(in srgb,var(--dm-k) 13%,var(--dm-surface))}
.dm-trv-nm{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-trv-r.dm-root .dm-trv-nm{font-weight:500}
.dm-trv-n .dm-tag{flex:none}
/* the tree: a guide from each parent's mark down past its children, with an elbow into each child */
.dm-trv-g{position:absolute;top:0;bottom:0;left:0;pointer-events:none}
.dm-trv-g i{position:absolute;top:0;bottom:0;left:calc(var(--dm-x) * 16px + 8.5px);width:1px;background:color-mix(in srgb,var(--dm-rail) 60%,transparent)}
.dm-trv-g i.dm-end{bottom:50%}
.dm-trv-g i.dm-el::after{content:"";position:absolute;left:0;top:calc(50% - 1px);width:7px;height:1px;background:inherit}
.dm-trv-g i.dm-end.dm-el::after{top:auto;bottom:-1px}
.dm-trv-g i.dm-dn{top:50%}
/* a bar per span on the shared axis: faint lines mark the ticks */
.dm-trv-b{position:relative;height:20px;background:linear-gradient(to right,var(--dm-line) 1px,transparent 1px) 0 0/20% 100%}
/* a bar is laid out once at its full length; while it runs, --f (0 to 1) reveals it with a clip and moves its bright edge with a
   transform, so a streaming run repaints without laying the page out again */
.dm-trv-b i{position:absolute;top:5px;height:10px;min-width:3px;border-radius:3px;clip-path:inset(-6px calc((1 - var(--dm-f,1)) * 100% - 2px) -6px -6px);background:linear-gradient(90deg,color-mix(in srgb,var(--dm-k) 70%,var(--dm-surface)),var(--dm-k));transition:background .3s,opacity .3s}
/* a running bar has a light passing along it and a bright leading edge */
.dm-trv-r.dm-run .dm-trv-b i{background:linear-gradient(90deg,color-mix(in srgb,var(--dm-k) 55%,var(--dm-surface)) 0 30%,color-mix(in srgb,var(--dm-k) 25%,var(--dm-surface)) 45%,var(--dm-k) 60% 100%) 0 0/250% 100%;animation:dm-trvsheen 1.4s linear infinite}
.dm-trv-r.dm-run:not([data-k="agent"]) .dm-trv-b i::after{content:"";position:absolute;left:0;right:0;top:-2px;bottom:-2px;--dm-e:var(--dm-k);background:linear-gradient(to left,var(--dm-e) 0 2px,transparent 2px);filter:drop-shadow(0 0 3px color-mix(in srgb,var(--dm-e) 70%,transparent));transform:translateX(calc(var(--dm-f,1) * 100% - 100% + 1px))}
@keyframes dm-trvsheen{from{background-position:100% 0}to{background-position:-150% 0}}
/* an agent span holds the others, so it is drawn as a bracket over the time they take */
.dm-trv-r[data-k="agent"] .dm-trv-b i,.dm-trv-r.dm-run[data-k="agent"] .dm-trv-b i{top:9px;height:2px;border-radius:1px;background:var(--dm-faint);animation:none}
.dm-trv-r[data-k="agent"] .dm-trv-b i::before,.dm-trv-r[data-k="agent"] .dm-trv-b i::after{content:"";position:absolute;top:-3px;width:2px;height:8px;border-radius:1px;background:var(--dm-faint)}
.dm-trv-r[data-k="agent"] .dm-trv-b i::before{left:0}.dm-trv-r[data-k="agent"] .dm-trv-b i::after{right:0}
.dm-trv-r.dm-run[data-k="agent"] .dm-trv-b i::after{background:var(--dm-muted)}
/* over budget: amber, hatched */
.dm-trv-r.dm-slow .dm-trv-b i,.dm-trv-r.dm-run.dm-slow .dm-trv-b i{background:repeating-linear-gradient(135deg,var(--dm-warn) 0 3px,color-mix(in srgb,var(--dm-warn) 55%,var(--dm-surface)) 3px 6px)}
.dm-trv-r.dm-run.dm-slow .dm-trv-b i::after{--dm-e:var(--dm-warn)}
.dm-trv-r .dm-trv-tk{font-size:12px;color:var(--dm-muted)}
.dm-trv-r .dm-trv-ms{font-size:12.5px;color:var(--dm-fg2)}
.dm-trv-r.dm-slow .dm-trv-ms{color:var(--dm-warn)}
/* with a span open, the other bars step back */
.dm-trv-rows.dm-sel .dm-trv-r:not([aria-expanded="true"]) .dm-trv-b i{opacity:.35}
/* the playhead: where the run is now, one line down every bar's track while it streams */
.dm-trv-b::after,.dm-trv-sc::after{content:"";position:absolute;left:0;right:0;top:-6px;bottom:-6px;background:linear-gradient(90deg,var(--dm-accent-mark,var(--dm-accent)) 0 1px,transparent 1px);transform:translateX(calc(var(--dm-now,0) * 100% - .5px));opacity:0;transition:opacity .4s;pointer-events:none}
.dm-trv-sc::after{top:12px;bottom:-6px}
.dm-trv.dm-live .dm-trv-b::after,.dm-trv.dm-live .dm-trv-sc::after{opacity:.75}
.dm-trv-dc{display:flex;flex-direction:column;gap:10px;margin-top:2px;padding:6px 10px var(--dm-s-2);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-trv-dh{display:flex;align-items:center;gap:var(--dm-s-2);min-width:0;font-size:13px}
.dm-trv-dh b{min-width:0;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-trv-dh .dm-ib{margin:0 -6px 0 auto}
/* where the open span sat in the run */
.dm-trv-pos{position:relative;height:6px;border-radius:3px;background:var(--dm-line)}
.dm-trv-pos i{position:absolute;top:0;bottom:0;min-width:3px;border-radius:3px;background:var(--dm-k);transition:width .25s linear}
.dm-trv-kv{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:var(--dm-s-2)}
.dm-trv-kv div{display:flex;flex-direction:column;min-width:0}
.dm-trv-kv span{font-size:12px;color:var(--dm-muted)}
.dm-trv-kv b{font-size:13px;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-trv-io{display:grid;grid-template-columns:auto minmax(0,1fr);align-items:center;gap:6px 10px;font-size:12px;color:var(--dm-muted)}
.dm-trv-io code{font-family:var(--dm-mono);font-size:12px;color:var(--dm-fg2);background:var(--dm-chip);padding:5px var(--dm-s-2);border-radius:var(--dm-r-sm);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
:root:not([data-style="soft"]) .dm-trv-r:not(.dm-slow) .dm-trv-b i:not(:where([data-style="soft"],[data-style="soft"] *)){background:var(--dm-k)}
:root:not([data-style="soft"]) .dm-trv-r.dm-run:not(.dm-slow):not([data-k="agent"]) .dm-trv-b i:not(:where([data-style="soft"],[data-style="soft"] *)){background:repeating-linear-gradient(90deg,var(--dm-k) 0 4px,color-mix(in srgb,var(--dm-k) 55%,var(--dm-surface)) 4px 6px);animation:none}
:root:not([data-style="soft"]) .dm-trv-r.dm-run:not([data-k="agent"]) .dm-trv-b i:not(:where([data-style="soft"],[data-style="soft"] *))::after{filter:none;background:linear-gradient(to left,var(--dm-e) 0 1px,transparent 1px);transform:translateX(calc(var(--dm-f,1) * 100% - 100%))}
:root:not([data-style="soft"]) .dm-trv-g i:not(:where([data-style="soft"],[data-style="soft"] *)),:root:not([data-style="soft"]) .dm-trv-g i.dm-el:not(:where([data-style="soft"],[data-style="soft"] *))::after{background:var(--dm-faint)}
/* narrow: the names keep their room. Tokens move into each span's details, the slow tag leaves the amber bar and time to
   say it (the time keeps its tooltip), the tree draws closer, and the details give the start its own line */
@container (max-width:330px){.dm-trv-ax,.dm-trv-r{grid-template-columns:minmax(0,1fr) 72px 44px}.dm-trv-tk,.dm-trv-n .dm-tag{display:none}.dm-trv-n{padding-left:calc(var(--dm-lv,0) * 10px)}.dm-trv-g{display:none}.dm-trv-kv{grid-template-columns:repeat(2,minmax(0,1fr))}}

